def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    desperate_count = 0
    rich_fixed_count = 0

    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 2:
                desperate_count += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                b = prev.get('bid', 0.0)
                prev_bids.append(b)
                if b >= 130:
                    rich_fixed_count += 1

    if not alive:
        return float(min(budget, 12.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    likely_units = int(supply / WATER_REQ)
    my_urgent = hp <= 2 or no_water >= 2
    caution = hp <= 4 or no_water >= 1

    if my_urgent:
        target = max(92.0, highest_prev + 2.0)
        if rich_fixed_count > 0:
            target = max(target, 136.0)
        return float(min(budget, target))

    if likely_units >= 2:
        if highest_prev >= 130:
            target = 41.0 if hp > 5 else 58.0
        elif highest_prev >= 85:
            target = 52.0 if hp > 5 else 67.0
        else:
            target = 38.0 if hp > 6 else 50.0
        if desperate_count >= 2:
            target += 8.0
        return float(min(budget, target))

    target = 0.0
    if rich_fixed_count > 0:
        if caution:
            target = 136.0
        else:
            target = 18.0
    else:
        if highest_prev >= 100:
            target = 24.0 if hp > 5 else 88.0
        elif highest_prev >= 70:
            target = highest_prev + 3.0 if caution else 33.0
        elif avg_prev > 0:
            target = max(36.0, avg_prev + 4.0)
        else:
            target = 42.0

    if desperate_count >= 2 and target < 80.0:
        target += 10.0

    target = min(target, budget)
    if target < 0:
        target = 0.0
    return float(target)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    hp = int(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        try:
            if opp.get('alive', False):
                alive_opps.append((opp_id, opp))
        except Exception:
            continue

    if not alive_opps:
        return min(budget, DAILY_SALARY * 0.4)

    # Read yesterday bids from traces to infer pressure.
    prev_bids = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    # Also check if any opponent was bidding extremely high (likely water-secure strategy).
    extreme_pressure = highest_prev_bid >= DAILY_SALARY * 1.45  # ~130+ given DAILY_SALARY=90

    # Estimate how many water units exist relative to our requirement.
    # This is only a heuristic for competition intensity.
    # supply is between 15 and 25; water units likely 1 or 2.
    units = int(supply / float(WATER_REQ))
    if units < 1:
        units = 1

    # Base bid policy: moderate unless our hp is low or opponent pressure is extreme.
    # When supply is higher (closer to 25), competition increases; bid slightly more.
    supply_frac = 0.0
    if MAX_SUPPLY > MIN_SUPPLY:
        supply_frac = (supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY)
    if supply_frac < 0.0:
        supply_frac = 0.0
    if supply_frac > 1.0:
        supply_frac = 1.0

    # HP urgency factor
    if hp <= 2 or no_water_days >= 2:
        hp_factor = 0.95
    elif hp <= 4:
        hp_factor = 0.75
    else:
        hp_factor = 0.55

    # Opponent pressure factor
    if extreme_pressure:
        # Don't fully mirror, but raise to avoid being outbid for the last unit.
        pressure_factor = 0.78 if units == 1 else 0.68
    else:
        pressure_factor = 0.62 if units == 1 else 0.55

    # Supply factor: bid more when supply is higher (more likely others also bid).
    supply_factor = 0.50 + 0.25 * supply_frac

    target = DAILY_SALARY * hp_factor * pressure_factor * supply_factor

    # If yesterday's highest bid was already moderate, try to be slightly above it when we can afford.
    if highest_prev_bid > 0.0 and highest_prev_bid < DAILY_SALARY * 1.2:
        # Only chase if we have enough budget; otherwise stick to target.
        chase = highest_prev_bid + 2.0
        # Allow slight overtake when hp is not critical.
        if hp >= 3:
            target = max(target, chase * 0.95)
        else:
            target = max(target, chase)

    # Hard caps to preserve budget.
    # Never bid above what we can pay.
    bid = min(budget, target)

    # Ensure non-negative.
    if bid < 0.0:
        bid = 0.0

    return bid
